// Read Request: the raw body (for the signature), the Slack headers and the interaction payload.
const item = $input.first();
const j = item.json || {};
const h = j.headers || {};
let raw = '', rawSource = 'none';
try {
  if (item.binary && item.binary.data) {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    raw = buf.toString('utf8'); rawSource = 'binary';
  }
} catch (e) { rawSource = 'binary-error: ' + String(e.message || e).slice(0, 80); }
if (!raw && typeof j.body === 'string') { raw = j.body; rawSource = 'body-string'; }
let payload = null, payloadSource = 'none';
if (j.body && j.body.payload) {
  try { payload = typeof j.body.payload === 'string' ? JSON.parse(j.body.payload) : j.body.payload; payloadSource = 'parsed-body'; } catch (e) {}
}
if (!payload) {
  try { const m = raw.match(/(?:^|&)payload=([^&]*)/); if (m) { payload = JSON.parse(decodeURIComponent(m[1].replace(/\+/g, ' '))); payloadSource = 'raw'; } } catch (e) {}
}
return [{ json: {
  raw, rawSource, rawLength: raw.length,
  sig: String(h['x-slack-signature'] || ''),
  ts: String(h['x-slack-request-timestamp'] || ''),
  payload: payload || {}, payloadSource,
  receivedAt: Date.now()
} }];

// To Sign: the string Slack signs - 'v0:' + timestamp + ':' + raw body - for Jessie — Slack Signature.
const r = $input.first().json;
return [{ json: { base: 'v0:' + r.ts + ':' + r.raw } }];

// v68 (PENDING 152): a Book a room button carrying everything step 1 asks (date, start + end or all day, booking type; no Repeats)
function __stepOneDone(value) {
  let g = null; try { g = JSON.parse(String(value || '')); } catch (e) { return false; }
  if (!g || typeof g !== 'object' || g.rep) return false;
  const p = String(g.p || ''), hm = x => /^([01]\d|2[0-3]):[0-5]\d$/.test(String(x || ''));
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(g.d || '')) || !p) return false;
  if (g.ad && (p === '__booth' || p === 'Event')) return true;
  return hm(g.s) && hm(g.e) && String(g.e) > String(g.s);
}
// Check Signature: Slack signs 'v0:' + timestamp + ':' + raw body (HMAC-SHA256, hex). Refuse a timestamp more than
// 5 minutes off. Then pick the route.
const r = $('Read Request').first().json;
const computed = String($input.first().json.computed || '');
const sigOk = !!r.sig && ('v0=' + computed) === r.sig;
const ageSec = r.ts ? Math.round(Date.now() / 1000 - Number(r.ts)) : null;
const fresh = ageSec !== null && Math.abs(ageSec) <= 300;
const p = r.payload || {};
const action = (p.actions && p.actions[0] && p.actions[0].action_id) || '';
const cb = (p.view && p.view.callback_id) || '';
const ROUTES = { refused: 0, hello_open: 1, hello_submit: 2, other: 3, open_book: 4, book_step1: 5, book_step2: 6, my_bookings: 7, note_toggle: 8, bk_cancel: 9, bk_change: 10, change_booking: 11, my_page: 12, series_confirm: 13, suggest: 14, rm_keep: 15, cr: 16, cr_cleared: 17, cr_cleared_submit: 18 };   // v37: room requests   // v24: suggest
let route = ROUTES.other;
if (!(sigOk && fresh)) route = ROUTES.refused;
else if (p.type === 'block_suggestion') route = ROUTES.other;   // v29: the project-code search is gone (a text box since v25)
else if (p.type === 'block_actions' && action === 'hello_open') route = ROUTES.hello_open;
else if (p.type === 'view_submission' && cb === 'hello_submit') route = ROUTES.hello_submit;
else if (p.type === 'block_actions' && action === 'book_continue') route = ROUTES.book_step1;   // v45: Continue booking - straight to step 2
else if (p.type === 'block_actions' && action === 'open_book' && __stepOneDone(((p.actions || [])[0] || {}).value)) route = ROUTES.book_step1;   // v68: straight to the free rooms
else if (p.type === 'block_actions' && (action === 'open_book' || action === 'cr_pick' || action === 'step1_back')) route = ROUTES.open_book;   // v37: Pick another room; v68: Change date or time
else if (p.type === 'block_actions' && action === 'my_bookings') route = ROUTES.my_bookings;
else if (p.type === 'block_actions' && ['note_toggle', 'repeat_toggle', 'rep_freq_pick', 'rep_days_pick', 'rep_count_pick', 'rep_until_pick', 'date_pick', 'details_toggle', 'room_toggle', 'add_booth', 'add_holding', 'allday_toggle', 'purpose_pick', 'room_radio', 'code_pick', 'forwho_toggle', 'purpose_c', 'room_other_pick', 'code_in', 'det_code_in', 'booth_pick', 'more_rooms_pick', 'holding_pick', 'booth_c_pick', 'holding_c_pick', 'more_c_pick', 'engineer_pick', 'arranger_pick', 'det_engineer_pick', 'det_arranger_pick', 'more_eng_pick', 'more_eng_c_pick', 'more_eng_toggle', 'more_eng_c_toggle'].indexOf(action) !== -1) route = ROUTES.note_toggle;   // v71: the tick   // v70: + the people multi-selects   // v64: the multi-selects (Picked: line)   // v10; v13 Repeats; v18 details; v21 room_toggle (v19 never routed it), booths, holding rooms, all day, purpose / studio redraws
else if (p.type === 'view_submission' && cb === 'series_confirm') route = ROUTES.series_confirm;   // v13
else if (p.type === 'block_actions' && action === 'bk_cancel') route = ROUTES.bk_cancel;   // v11
else if (p.type === 'block_actions' && (action === 'bk_change' || action === 'cr_move')) route = ROUTES.bk_change;   // v37: Move my booking
else if (p.type === 'block_actions' && ['cr_keep', 'cr_giveup', 'cr_allow', 'cr_withdraw', 'cr_attest'].indexOf(action) !== -1) route = ROUTES.cr;   // v37
else if (p.type === 'block_actions' && action === 'cr_cleared') route = ROUTES.cr_cleared;   // v37
else if (p.type === 'view_submission' && cb === 'cr_cleared') route = ROUTES.cr_cleared_submit;   // v37
else if (p.type === 'block_actions' && action === 'rm_keep') route = ROUTES.rm_keep;   // v35: a reminder's Still on / Keep
else if (p.type === 'block_actions' && /^my_page/.test(action)) route = ROUTES.my_page;   // v16: my_page_prev / my_page_next
else if (p.type === 'view_submission' && cb === 'change_booking') route = ROUTES.change_booking;
else if (p.type === 'view_submission' && cb === 'book_step1') route = ROUTES.book_step1;
else if (p.type === 'view_submission' && cb === 'book_step2') route = ROUTES.book_step2;
return [{ json: { route, sigOk, fresh, ageSec, type: p.type || '', action, cb,
  user: (p.user && p.user.id) || '', triggerId: p.trigger_id || '', viewId: (p.view && p.view.id) || '',
  channel: (p.channel && p.channel.id) || (p.container && p.container.channel_id) || '',
  rawSource: r.rawSource, rawLength: r.rawLength, payloadSource: r.payloadSource, receivedAt: r.receivedAt } }];

// Refused: the signature or the timestamp did not check out - tell the tester why (nothing else happens).
const c = $('Check Signature').first().json;
// v29: no Slack timestamp header -> not Slack (curl, a link preview, a scanner - 19 Oct 16:03): refused quietly, no DM
if (c.ageSec === null || c.ageSec === undefined) return [];
const lines = ['*Slack Interactions - a request was refused*',
  '• Signature: ' + (c.sigOk ? 'OK' : 'did not match') + ' · timestamp age ' + c.ageSec + ' s (allowed: 300)',
  '• Raw body: ' + c.rawSource + ' (' + c.rawLength + ' chars) · payload from ' + c.payloadSource + ' · type ' + (c.type || '?'),
  'If the signature did not match: check the secret in the Sign node of Jessie — Slack Signature, and that the Webhook node has Raw Body on.'];
return [{ json: { channel: 'U08V3CKDGJF', text: lines.join('\n') } }];

// Build Form: the hello form (diagnostics). The date picker opens a year ahead (the QA year shift).
const c = $('Check Signature').first().json;
const m = new Date(Date.now() + 8 * 3600 * 1000);
const d = (m.getUTCFullYear() + 1) + '-' + String(m.getUTCMonth() + 1).padStart(2, '0') + '-' + String(m.getUTCDate()).padStart(2, '0');
const view = { type: 'modal', callback_id: 'hello_submit', title: { type: 'plain_text', text: 'Hello form' },
  submit: { type: 'plain_text', text: 'Send' }, close: { type: 'plain_text', text: 'Cancel' },
  blocks: [
    { type: 'section', text: { type: 'mrkdwn', text: 'Test form for the Slack-app build. Pick a date, type anything, press *Send*.' } },
    { type: 'input', block_id: 'date', label: { type: 'plain_text', text: 'Date' }, element: { type: 'datepicker', action_id: 'date_pick', initial_date: d } },
    { type: 'input', block_id: 'note', label: { type: 'plain_text', text: 'Say something' }, element: { type: 'plain_text_input', action_id: 'note_in' } } ] };
return [{ json: { trigger_id: c.triggerId, view } }];

// Report Open: say if views.open failed (the trigger_id lasts 3 seconds).
const r = $input.first().json;
if (r.ok === true) return [];
const c = $('Check Signature').first().json;
return [{ json: { channel: c.user || 'U08V3CKDGJF', text: '⚠️ The form did not open: ' + JSON.stringify(r).slice(0, 300) } }];

// Read Submission (hello form).
const c = $('Check Signature').first().json;
const p = $('Read Request').first().json.payload || {};
const v = (p.view && p.view.state && p.view.state.values) || {};
const date = (v.date && v.date.date_pick && v.date.date_pick.selected_date) || '';
const note = (v.note && v.note.note_in && v.note.note_in.value) || '';
const view = (text) => ({ type: 'modal', title: { type: 'plain_text', text: 'Hello form' }, close: { type: 'plain_text', text: 'Close' },
  blocks: [{ type: 'section', text: { type: 'mrkdwn', text } }] });
return [{ json: { viewId: c.viewId, user: c.user || 'U08V3CKDGJF', date, note,
  working: { response_action: 'update', view: view('⏳ *Working…*') },
  done: view('✅ *Done.* Details are in your DM.') } }];

// Report (hello form).
const s = $('Read Submission').first().json;
const c = $('Check Signature').first().json;
const lines = ['*Hello form - result*',
  '• Signature check: ' + (c.sigOk ? 'OK' : 'FAILED') + ' · request age ' + c.ageSec + ' s',
  '• Raw body: ' + c.rawSource + ' (' + c.rawLength + ' chars) · payload from ' + c.payloadSource,
  '• Date picked: ' + (s.date || '(none)') + ' · note: ' + (s.note || '(empty)'),
  '• Update call: ' + ($('Update Form').first().json.ok === true ? 'OK' : 'FAILED ' + JSON.stringify($('Update Form').first().json).slice(0, 150))];
return [{ json: { channel: s.user, text: lines.join('\n') } }];

// v21: the Booth picker for a studio - the free vocal booths, the studio's usual one first (Airtable "Paired with")
function boothBlocks(studio, BX) {   // v25: a dropdown, always shown - set to the usual booth when the session needs one
  if (!BX) return [];
  const pt = x => ({ type: 'plain_text', text: String(x).slice(0, 150) });
  const raw = BX.pair && BX.pair[studio], free = [].concat(BX.list || []);
  const pref = Array.isArray(raw) ? raw : (raw && raw.usual ? [raw.usual] : []);
  const list = raw && raw.list ? [].concat(raw.list) : pref.filter(b => free.indexOf(b) !== -1).concat(free.filter(b => pref.indexOf(b) === -1));
  const usual = pref[0] || '';
  const bid = 'booth~' + (Date.now() % 1000000);   // a new block each time: a new studio's booths, nothing kept from the last
  if (!list.length) return [{ type: 'context', block_id: bid, elements: [{ type: 'mrkdwn', text: '⚠️ No vocal booth is free then' + (BX.need ? ' - ' + studio + ' can still be booked on its own.' : '.') }] }];
  // v53 (Howard, 28 Oct): several vocal booths - a multi-select; the usual booth preset when the session needs one (then at least
  // one - a required field), else empty = no booth (a picked booth can be removed on a phone too, so no "No booth" item). The
  // engineer / arranger dropdowns stay v39's: required (no Slack "Clear selection"), "No …" picked - a phone shows no clear line
  const opts = list.slice(0, 100).map(n => ({ text: pt(n + (n === usual ? ' (usual)' : '')), value: n }));
  const el = Object.assign({ type: 'multi_static_select', action_id: 'booth_pick', placeholder: pt(BX.need ? 'Select a booth' : 'No booth'), options: opts }, BX.need ? { initial_options: [opts[0]] } : {});
  return [Object.assign({ type: 'input', dispatch_action: true, block_id: bid, label: pt('Vocal booths'), element: el }, BX.need ? {} : { optional: true })];
}
// v21: M booth - all day, or the chosen times
const ALLDAY_BLOCK = { type: 'actions', block_id: 'allday_toggle', elements: [{ type: 'checkboxes', action_id: 'allday_toggle',
  options: [{ text: { type: 'plain_text', text: 'All day booking' }, value: 'allday' }] }] };

// The newest valid row of the Jessie Reference Cache data table (same check as main's Reference Snapshot).
function readCache(rows) {
  let best = null;
  for (const r of rows || []) {
    if (!r || r.cache_key !== 'jessie-reference') continue;
    let d; try { d = JSON.parse(r.payload); } catch (e) { continue; }
    if (!d || !Array.isArray(d.rooms) || !Array.isArray(d.sessionTypes) || !Array.isArray(d.bookers)) continue;
    const at = Date.parse(r.refreshed_at || '') || 0;
    if (!best || at > best.at) best = { at, d };
  }
  return best ? best.d : null;
}

// The Repeats fields (v13; one function since v14 - the ticked box and a typed series both use it): How often, On (the
// days, for every week), How many times, Or until. rep = {f, days, n, u} fills them in; otherwise every week on the
// first date's day.
// v60 (Howard, 3 Nov): a series starts on the date chosen - always its first booking - then the days ticked after it,
// until How many times or the end date (How many times wins). The form's live line and step 1's check use this one rule.
function repSeries(date, freq, days, count, until) {
  const K = { SU: 0, MO: 1, TU: 2, WE: 3, TH: 4, FR: 5, SA: 6 };
  let ds = [].concat(days || []);
  if (!ds.length && freq === 'weekdays') ds = ['MO', 'TU', 'WE', 'TH', 'FR'];
  if (!ds.length && freq === 'daily') ds = Object.keys(K);
  const want = new Set(ds.map(d => K[d]));
  const out = [];
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(date || ''))) return out;
  const cur = new Date(date + 'T12:00:00Z');
  for (let g = 0; g < 800; g++) {
    const d = cur.toISOString().slice(0, 10);
    if (until && d > until) break;
    if (g === 0 || want.has(cur.getUTCDay())) out.push(d);
    if (count && out.length >= count) break;
    if (!count && !until) break;
    cur.setUTCDate(cur.getUTCDate() + 1);
  }
  return out;
}
function repList(ds) {
  const W = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], M = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const p = d => { const x = new Date(d + 'T12:00:00Z'); return { w: W[x.getUTCDay()], d: x.getUTCDate(), m: M[x.getUTCMonth()], y: x.getUTCFullYear() }; };
  if (ds.length > 8) { const a = p(ds[0]), b = p(ds[ds.length - 1]); return a.w + ' ' + a.d + ' ' + a.m + ' – ' + b.w + ' ' + b.d + ' ' + b.m + (a.y !== b.y ? ' ' + b.y : ''); }
  const parts = []; let cur = null;
  for (const d of ds) { const x = p(d); if (cur && cur.m !== x.m) parts[parts.length - 1] += ' ' + cur.m; parts.push(x.w + ' ' + x.d); cur = x; }
  if (cur) parts[parts.length - 1] += ' ' + cur.m;
  return parts.join(', ');
}
function repTooMany(n) { return 'That runs past 6 months – the most is 6 months from the first date. Pick an earlier end date or fewer times.'; }   // v66
function repTooLong(ds) { if (!ds || !ds.length) return false; const l = new Date(ds[0] + 'T12:00:00Z'); l.setUTCMonth(l.getUTCMonth() + 6);
  return ds[ds.length - 1] > l.toISOString().slice(0, 10) || ds.length > 200; }   // v66 (PENDING 150): six months, not 16 dates
function repNote(date, freq, days, count, until) {
  count = Number(count || 0); until = String(until || '');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(date || ''))) return 'Pick the first date. Up to 6 months.';
  if (freq === 'weekly' && ![].concat(days || []).length) return 'Tick at least one day.';
  if (!count && !until) return 'Pick *How many times* or an end date. Up to 6 months.';
  if (!count && until <= date) return 'The end date has to be after the first date.';
  const ds = repSeries(date, freq, days, count, count ? '' : until);
  if (repTooLong(ds)) return '⚠️ ' + repTooMany(ds.length);
  if (ds.length < 2) return 'That’s only one date – untick Repeats for a single booking.';
  return '🔁 *Books ' + ds.length + ' dates:* ' + repList(ds);
}
function repBlocks(date, rep) {
  rep = rep || {};
  const pt = x => ({ type: 'plain_text', text: x });
  const K = ['SU', 'MO', 'TU', 'WE', 'TH', 'FR', 'SA'], NAMES = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const dayOpts = [1, 2, 3, 4, 5, 6, 0].map(i => ({ text: pt(NAMES[i]), value: K[i] }));
  const wd = /^\d{4}-\d{2}-\d{2}$/.test(String(date || '')) ? new Date(date + 'T12:00:00Z').getUTCDay() : 1;
  const freq = [{ text: pt('Weekly'), value: 'weekly' }, { text: pt('Weekdays'), value: 'weekdays' }, { text: pt('Daily'), value: 'daily' }];   // v30: shorter labels, same values
  const counts = []; for (let i = 2; i <= 60; i++) counts.push({ text: pt(i + ' times'), value: String(i) });
  counts.push({ text: pt('Use the end date'), value: '0' });   // v39: a phone cannot clear a picked number - this hands over to "Or until"
  const days = [].concat(rep.days || []).filter(k => K.indexOf(k) !== -1);
  // v57: none given -> How often's days: Weekly the first date's day, Weekdays Mon-Fri, Daily all seven
  const preset = rep.f === 'weekdays' ? ['MO', 'TU', 'WE', 'TH', 'FR'] : rep.f === 'daily' ? K.slice() : [K[wd]];
  const dIni = dayOpts.filter(o => (days.length ? days : preset).indexOf(o.value) !== -1);
  const cIni = counts.find(o => o.value === String(rep.n || ''));
  // v60: no pre-filled "Or until" (v15 opened it four weeks out for the QA year; for Weekdays / Daily that was over 16 dates)
  const u0 = /^\d{4}-\d{2}-\d{2}$/.test(String(rep.u || '')) ? rep.u : '';
  const until = Object.assign({ type: 'datepicker', action_id: 'rep_until_pick', placeholder: pt('Select a date') }, u0 ? { initial_date: u0 } : {});
  return [
    { type: 'input', block_id: 'rep_freq', dispatch_action: true, label: pt('How often?'), element: { type: 'static_select', action_id: 'rep_freq_pick', placeholder: pt('Select how often'), options: freq, initial_option: freq.find(o => o.value === rep.f) || freq[0] } },
    { type: 'input', block_id: 'rep_days', optional: true, dispatch_action: true, label: pt('On'),
      element: { type: 'checkboxes', action_id: 'rep_days_pick', options: dayOpts, initial_options: dIni } },
    { type: 'input', block_id: 'rep_count', optional: true, dispatch_action: true, label: pt('How many times'), element: Object.assign({ type: 'static_select', action_id: 'rep_count_pick', placeholder: pt('Select a number'), options: counts }, cIni ? { initial_option: cIni } : {}) },
    { type: 'input', block_id: 'rep_until', optional: true, dispatch_action: true, label: pt('Or until'), hint: pt('Only applies if "How many times" is empty.'), element: until },
    { type: 'context', block_id: 'rep_note', elements: [{ type: 'mrkdwn', text: repNote(date, rep.f || 'weekly', days.length ? days : preset, rep.n, u0) }] }];   // v60: live
}

// Build Step 1: date, start, end, what it's for. Session types from the reference cache; the date picker opens on
// Manila's today a year ahead (QA year shift - at launch: YEAR_SHIFT = 0).
const YEAR_SHIFT = 0;
const c = $('Check Signature').first().json;
const data = readCache($('Read Cache').all().map(i => i.json || {}));
const types = data ? data.sessionTypes.map(r => String((r.fields || {}).Type || '').trim()).filter(Boolean) : [];
const NOT_SESSION = ['Meeting', 'Event'];
const sessions = types.filter(t => NOT_SESSION.indexOf(t) === -1).sort();
const opt = (t, v) => ({ text: { type: 'plain_text', text: t }, value: v || t });
const groups = [];
if (sessions.length) groups.push({ label: { type: 'plain_text', text: 'Sessions' }, options: sessions.slice(0, 100).map(t => opt(t)) });
groups.push({ label: { type: 'plain_text', text: 'Other bookings' },
  options: NOT_SESSION.filter(t => types.indexOf(t) !== -1).map(t => opt(t)).concat([opt('M booth', '__booth')]) });
// Start / End: half-hour times, the list opening at 6:00 AM and running round to 5:30 AM (v42) (all bookable, read as PHT).
const times = [];
for (let i = 0; i < 48; i++) { const mins = (6 * 60 + i * 30) % (24 * 60), h = Math.floor(mins / 60), mm = mins % 60;
  times.push({ text: { type: 'plain_text', text: ((h % 12) || 12) + ':' + String(mm).padStart(2, '0') + ' ' + (h < 12 ? 'AM' : 'PM') },
               value: String(h).padStart(2, '0') + ':' + String(mm).padStart(2, '0') }); }
// v42: the End list ends the day at 11:59 PM (in place of 12:00 AM) - 12:00 AM to 11:59 PM is the whole day
const END_MID = { text: { type: 'plain_text', text: '11:59 PM' }, value: '23:59' };
const timeEl = (id, o) => Object.assign({ type: 'static_select', action_id: id, placeholder: { type: 'plain_text', text: id === 'end_pick' ? 'Select an end time' : 'Select a start time' }, options: id === 'end_pick' ? times.map(x => x.value === '00:00' ? END_MID : x) : times }, o ? { initial_option: o } : {});
// v9: what main read from a typed request rides on the button's value (the menu's button says "menu": nothing to fill in)
let pre = {};
try { const a = ((($('Read Request').first().json.payload || {}).actions) || [])[0] || {}; if (/^\{/.test(String(a.value || ''))) pre = JSON.parse(a.value) || {}; } catch (e) { pre = {}; }
const hm = x => /^([01]\d|2[0-3]):[0-5]\d$/.test(String(x || '')) ? String(x) : '';
const tOpt = v => { let o = times.find(x => x.value === v); if (o) return o;
  const [h, mm] = v.split(':').map(Number); o = { text: { type: 'plain_text', text: ((h % 12) || 12) + ':' + String(mm).padStart(2, '0') + ' ' + (h < 12 ? 'AM' : 'PM') }, value: v };
  const key = x => (Number(x.split(':')[0]) * 60 + Number(x.split(':')[1]) - 360 + 1440) % 1440;   // the list's order: from 6:00 AM round (v42)
  const at = times.findIndex(x => key(x.value) > key(v)); times.splice(at === -1 ? times.length : at, 0, o); return o; };
const preS = hm(pre.s), preE = hm(pre.e);
const startOpt = preS ? tOpt(preS) : null, endOpt = preE ? (preE === '23:59' || preE === '00:00' ? END_MID : tOpt(preE)) : null;   // v42
const allPurpose = [].concat(...groups.map(gr => gr.options));
