function roomMain(r) { const a = roomList(r); if (a[0] && !/^(?:Studio\s|M\d)/i.test(a[0])) return a.join(' + ');   // v53: a meeting in several rooms ("Likha + Katha")
  return [a[0]].concat(a.slice(1).filter(x => /^(?:Studio\s|M\d)/i.test(x))).filter(Boolean).join(' + '); }
