function bkCard(b, head) { return head + '\n\n*' + b.t + '*\n*Date:* ' + dayLong(b.d) + '\n*Time:* ' + (b.s && !(b.s === '00:00' && b.e === '00:00') ? t12(b.s) + ' – ' + t12(b.e) : 'All day') + '\n*Room:* ' + (roomMain(b.r) || '-') + (roomHold(b.r) ? '\n*Holding room:* ' + roomHold(b.r) : '') + noteLine(b.nt); }
// a Google event -> a booking (Manila times; the room from its room attendee, else its location)
