    const to = (!DEV_REDIRECT || ALLOW.indexOf(x.id) !== -1) ? x.id : DEV_REDIRECT;
    const text = (to !== x.id ? '[DEV] would notify ' + (x.name || x.id) + ' (' + x.id + '):\n' : '') + '👋 *' + actorName + ' ' + (x.line || (x.verb + ' you as the ' + x.role + (x.extra || ''))) + '.*\n\n' + body;   // v24: x.line
